public int singleNumber(int[] nums) {
    int result = 0;
    for (int num : nums) result ^= num;
    return result;
}

public int singleNumberII(int[] nums) {
    int result = 0;
    for (int i = 0; i < 32; i++) {
        int count = 0;
        for (int num : nums) {
            count += (num >> i) & 1;
        }
        if (count % 3 != 0) {
            result |= (1 << i);
        }
    }
    return result;
}

public int[] singleNumberIII(int[] nums) {
    int xorAll = 0;
    for (int num : nums) xorAll ^= num;
    int diffBit = xorAll & -xorAll;
    int a = 0, b = 0;
    for (int num : nums) {
        if ((num & diffBit) != 0) a ^= num;
        else b ^= num;
    }
    return new int[]{a, b};
}

public int[] countBits(int n) {
    int[] dp = new int[n + 1];
    for (int i = 1; i <= n; i++) {
        dp[i] = dp[i >> 1] + (i & 1);
    }
    return dp;
}
public int hammingWeight(int n) {
    int count = 0;
    while (n != 0) {
        n &= (n - 1);
        count++;
    }
    return count;
}

public boolean isPowerOfTwo(int n) {
    return n > 0 && (n & (n - 1)) == 0;
}
public int reverseBits(int n) {
    int result = 0;
    for (int i = 0; i < 32; i++) {
        result <<= 1;
        result |= (n & 1);
        n >>>= 1;
    }
    return result;
}

public int getSum(int a, int b) {
    while (b != 0) {
        int carry = (a & b) << 1;
        a = a ^ b;
        b = carry;
    }
    return a;
}
public int divide(int dividend, int divisor) {
    if (dividend == Integer.MIN_VALUE && divisor == -1) return Integer.MAX_VALUE;
    boolean negative = (dividend < 0) ^ (divisor < 0);
    long a = Math.abs((long) dividend), b = Math.abs((long) divisor);
    long result = 0;
    while (a >= b) {
        long temp = b, multiple = 1;
        while (a >= (temp << 1)) {
            temp <<= 1;
            multiple <<= 1;
        }
        a -= temp;
        result += multiple;
    }
    return negative ? (int) -result : (int) result;
}

public List<List<Integer>> subsets(int[] nums) {
    int n = nums.length;
    List<List<Integer>> result = new ArrayList<>();
    for (int mask = 0; mask < (1 << n); mask++) {
        List<Integer> subset = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if ((mask & (1 << i)) != 0) subset.add(nums[i]);
        }
        result.add(subset);
    }
    return result;
}

public int shortestPathLength(int[][] graph) {
    int n = graph.length;
    int allVisited = (1 << n) - 1;
    int[][] dist = new int[1 << n][n];
    for (int[] row : dist) Arrays.fill(row, Integer.MAX_VALUE);
    Queue<int[]> queue = new LinkedList<>();
    for (int i = 0; i < n; i++) {
        dist[1 << i][i] = 0;
        queue.offer(new int[]{1 << i, i});
    }
    while (!queue.isEmpty()) {
        int[] curr = queue.poll();
        int mask = curr[0], node = curr[1];
        if (mask == allVisited) return dist[mask][node];
        for (int next : graph[node]) {
            int newMask = mask | (1 << next);
            if (dist[mask][node] + 1 < dist[newMask][next]) {
                dist[newMask][next] = dist[mask][node] + 1;
                queue.offer(new int[]{newMask, next});
            }
        }
    }
    return 0;
}

public List<Integer> grayCode(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 0; i < (1 << n); i++) {
        result.add(i ^ (i >> 1));
    }
    return result;
}
